import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["工時紀錄"]

# Step 1: 清除「員工」欄位前後空白 (B欄)
for row in ws.iter_rows(min_row=2, max_row=ws.max_row, min_col=2, max_col=2):
    for cell in row:
        if cell.value and isinstance(cell.value, str):
            cell.value = cell.value.strip()

# Step 2: 若「專案」欄位為空，填寫「未知」 (C欄)
for row in ws.iter_rows(min_row=2, max_row=ws.max_row, min_col=3, max_col=3):
    for cell in row:
        if cell.value is None or str(cell.value).strip() == "":
            cell.value = "未知"

# Step 3: 在最右邊新增「費用」欄，公式為時數 × 費率
expense_col = ws.max_column + 1
expense_header = "費用"
ws.cell(row=1, column=expense_col, value=expense_header)

for row in ws.iter_rows(min_row=2, max_row=ws.max_row, min_col=1, max_col=ws.max_column - 1):
    hours_cell = row[5]   # F欄 (時數)
    rate_cell = row[6]    # G欄 (費率)
    if hours_cell.value is not None and rate_cell.value is not None:
        expense_cell = ws.cell(row=hours_cell.row, column=expense_col)
        expense_cell.value = hours_cell.value * rate_cell.value

# Step 4: 刪除「費用」小於 5460 的行 (從最後一行往上刪，避免索引錯位)
expense_col_index = expense_col
rows_to_delete = []
for row in ws.iter_rows(min_row=2, max_row=ws.max_row):
    expense_cell = row[expense_col_index - 1]
    if expense_cell.value is not None and expense_cell.value < 5460:
        rows_to_delete.append(expense_cell.row)

for row_num in sorted(rows_to_delete, reverse=True):
    ws.delete_rows(row_num)

# Step 5: 將剩下的資料按「費用」降序排列
data_rows = []
header_row = []
for i, row in enumerate(ws.iter_rows(values_only=True)):
    if i == 0:
        header_row = list(row)
    else:
        data_rows.append(list(row))

data_rows.sort(key=lambda x: x[expense_col_index - 1] if x[expense_col_index - 1] is not None else 0, reverse=True)

# 清除現有資料（保留標題）
for row in ws.iter_rows(min_row=2, max_row=ws.max_row):
    for cell in row:
        cell.value = None

# 寫回排序後的資料
for i, data_row in enumerate(data_rows, start=2):
    for j, value in enumerate(data_row, start=1):
        ws.cell(row=i, column=j, value=value)

# Step 6: 在表格底部加入一行總計
total_row = ws.max_row + 1
ws.cell(row=total_row, column=1, value="總計")

# 計算時數與費用總和
total_hours = 0
total_expense = 0
for row in ws.iter_rows(min_row=2, max_row=total_row - 1):
    hours = row[5].value  # F欄 (時數)
    expense = row[expense_col_index - 1].value
    if hours is not None:
        total_hours += hours
    if expense is not None:
        total_expense += expense

ws.cell(row=total_row, column=6, value=total_hours)      # F欄 (時數)
ws.cell(row=total_row, column=expense_col_index, value=total_expense)  # 費用欄

wb.save(OUTPUT_PATH)
```

