import openpyxl
from openpyxl import load_workbook
from copy import copy

wb = load_workbook(INPUT_PATH)
ws_orders = wb["訂單"]

# 找出所有類別
categories = set()
for row in ws_orders.iter_rows(min_row=2, max_row=ws_orders.max_row, min_col=5, max_col=5):
    for cell in row:
        if cell.value:
            categories.add(cell.value)

# 為每個類別建立工作表
for category in categories:
    new_ws = wb.create_sheet(title=category)

    # 複製標題列（粗體格式）
    for col_idx, cell in enumerate(ws_orders[1], start=1):
        new_cell = new_ws.cell(row=1, column=col_idx, value=cell.value)
        if cell.font and cell.font.bold:
            new_cell.font = copy(cell.font)

    # 根據類別篩選資料列
    new_row = 2
    for row in ws_orders.iter_rows(min_row=2, max_row=ws_orders.max_row):
        if row[4].value == category:  # E 欄是類別
            for col_idx, cell in enumerate(row, start=1):
                new_cell = new_ws.cell(row=new_row, column=col_idx, value=cell.value)
                if cell.font:
                    new_cell.font = copy(cell.font)
                if cell.number_format:
                    new_cell.number_format = cell.number_format
            new_row += 1

wb.save(OUTPUT_PATH)
